def project_rule(n, pts, marks):
 m=set(marks); a=[[0]*n for _ in range(n)]
 for r,c,v in pts:a[r][c]=v
 for r,c in marks:a[r][c]=3
 for orient in ['h','v']:
  for r,c,v in pts:
   for dr,dc in ([(0,-1),(0,1)] if orient=='h' else [(-1,0),(1,0)]):
    rr,cc=r+dr,c+dc
    while 0<=rr<n and 0<=cc<n:
     if (rr,cc) in m and abs(rr-r)+abs(cc-c)!=1: break
     if a[rr][cc]!=3:a[rr][cc]=v
     rr+=dr;cc+=dc
 return a
pts2=[(2,2,5),(3,8,6),(6,5,8)]
marks2=[(1,2),(3,2),(2,1),(2,3),(2,8),(4,8),(3,7),(3,9),(5,5),(7,5),(6,4),(6,6)]
print('\n'.join(' '.join(map(str,x)) for x in project_rule(10,pts2,marks2)))
